76	// Simple ELF parsing structures
77	struct Elf32_Ehdr {
78	  unsigned char e_ident[16];
79	  uint16_t e_type;
80	  uint16_t e_machine;
81	  uint32_t e_version;
82	  uint32_t e_entry;
83	  uint32_t e_phoff;
84	  uint32_t e_shoff;
85	  uint32_t e_flags;
86	  uint16_t e_ehsize;
87	  uint16_t e_phentsize;
88	  uint16_t e_phnum;
89	  uint16_t e_shentsize;
90	  uint16_t e_shnum;
91	  uint16_t e_shstrndx;
92	};
93	
94	struct Elf32_Phdr {
95	  uint32_t p_type;
96	  uint32_t p_offset;
97	  uint32_t p_vaddr;
98	  uint32_t p_paddr;
99	  uint32_t p_filesz;
100	  uint32_t p_memsz;
101	  uint32_t p_flags;
102	  uint32_t p_align;
103	};
104	
105	#define PT_LOAD 1
106	
107	} // namespace
108	
109	bool SramBackdoorLoad(uint64_t global_addr, const uint8_t *data, size_t len) {
110	  bool load_ok = false;
111	  // Sweep all SRAMs, until we find the correct one or exhaust our options.
112	  for (const auto &[base, sram] : registered_srams) {
113	    if (ApplyLoadToSram(*sram, global_addr, data, len)) {
114	      load_ok = true;
115	    }
116	  }
117	  return load_ok;
118	}
